result:
**The bug:** `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === Math.floor(Date.now() / 1000)` (token expires *at* this exact second), the check passes and the token is accepted. Fix: change to `<=`.

**Secondary issue:** The manual expiry check is also redundant — `jwt.verify` already throws `TokenExpiredError` for expired tokens. The manual check only catches a subset of cases and has this boundary bug. The catch block should handle JWT errors specifically instead.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify already rejects expired tokens (using <=), so the
    // manual exp check is redundant and was also using < instead of <=.
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected errors (e.g. missing JWT_SECRET) should not leak details
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**
- Removed the buggy manual `exp` check — `jwt.verify` handles expiry correctly with `<=` internally
- Split the catch into `TokenExpiredError` vs `JsonWebTokenError` for distinct client messages
- Added a 500 fallback for unexpected errors (e.g. `JWT_SECRET` not set) so internal details don't leak
